    public static final String STATUS_CANDIDATE_NOT_ACTIVE = "CANDIDATE_NOT_ACTIVE";

    /**
     * 一个年度的候选行（与 CSV 一行对应）：阈值、基线、差值、置信区间、检验与复核建议。
     */
    public record Candidate(short year, String operator, double threshold, double baseline, double delta,
                            double ciLow, double ciHigh, Double flipRate, long positive, int availableDays,
                            int expectedDays, short trainStart, short trainEnd, Double evaluationJ,
                            boolean directionChanged, String adoptionStatus, String adoptionLabel) {
    }

